/*
 * A045102  Numbers whose base-4 representation contains exactly three 1's and
 *          two 2's.
 * https://oeis.org/A045102
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   not stated
 * Range:     u8 none, u16 n <= 38, u32 n <= 38, u64 n <= 38, u128 n <= 38,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  OEIS A045102
 *  Numbers whose base‑4 representation contains exactly three 1's
 *  and exactly two 2's.  The sequence is generated by exhaustive
 *  enumeration of base‑4 numbers in increasing order, stopping
 *  when the requested term is found.
 */

#include <stddef.h>  /* for size_t, needed in some implementations */

/* Helper: depth‑first search over the digits of a single length.  */
static void dfs(idx_t len, idx_t pos,
                int r1, int r2, int ro,
                seq_t val,
                idx_t target,
                idx_t *count, seq_t *result)
{
    if (*count == target) return;            /* already found */

    if (pos == len) {                        /* finished a number    */
        if (r1 == 0 && r2 == 0 && ro == 0) { /* valid construction   */
            (*count)++;
            if (*count == target) *result = val;
        }
        return;
    }

    /* Iterate digits in numeric order (lexicographic for base‑4).  */
    for (int d = (pos == 0) ? 1 : 0; d <= 3; ++d) {
        if (d == 1 && r1 == 0) continue;
        if (d == 2 && r2 == 0) continue;
        if ((d == 0 || d == 3) && ro == 0) continue;

        int nr1 = r1, nr2 = r2, nro = ro;
        if (d == 1) nr1--;
        else if (d == 2) nr2--;
        else nro--;

        dfs(len, pos + 1, nr1, nr2, nro,
            val * 4 + d,
            target, count, result);

        if (*count == target) return; /* early exit after finding nth term */
    }
}

/*  Main sequence function - external linkage.  */
seq_t a(idx_t n)
{
    idx_t target = n;            /* 1‑based index */
    idx_t count  = 0;            /* how many terms have been seen */
    seq_t result = 0;

    for (idx_t len = 5; /* minimal length */; ++len) {
        /* start a new search for numbers of this length */
        dfs(len, 0, 3, 2, /* 3 ones, 2 twos */ (int)(len - 5),
            0, target, &count, &result);

        if (count == target) break;  /* found the nth term */
    }
    return result;
}
